// Shared configuration for the RAST E2E harness.
//
// Credentials and the base URL come from tests/e2e/.env.local, generated by
// scripts/e2e/dev-instance.sh (git-ignored). Nothing here talks to the
// production instance: the dev server listens on 127.0.0.1:8731 (8721 is the
// host's nginx reverse proxy for the production instance on 8720).

import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const E2E_DIR = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const REPO_DIR = resolve(E2E_DIR, "../..");
export const FIXTURES_DIR = join(REPO_DIR, "tests/e2e/fixtures");
export const RESULTS_DIR = join(REPO_DIR, "tests/e2e/results");
export const SCREENSHOTS_DIR = join(REPO_DIR, "tests/e2e/screenshots");
export const TMP_DIR = join(REPO_DIR, "tests/e2e/tmp");

function readEnvFile(path) {
  const values = {};
  if (!existsSync(path)) return values;
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const index = trimmed.indexOf("=");
    if (index < 0) continue;
    values[trimmed.slice(0, index).trim()] = trimmed.slice(index + 1).trim();
  }
  return values;
}

// Instance isolation: each dev instance root has its own credentials.env
// (written by scripts/e2e/dev-instance.sh). RAST_E2E_ROOT selects the
// instance; the legacy tests/e2e/.env.local is only a fallback so several
// instances can coexist (docker on 8731, native on 8732) without one run
// silently pointing at the other one.
export const INSTANCE_ROOT = process.env.RAST_E2E_ROOT || "/tmp/rast-e2e";
const instanceEnv = readEnvFile(
  process.env.RAST_E2E_ENV || join(INSTANCE_ROOT, "credentials.env"),
);
const fallbackEnv = readEnvFile(join(E2E_DIR, ".env.local"));
const fileEnv = { ...fallbackEnv, ...instanceEnv };
const env = { ...fileEnv, ...process.env };

export const config = {
  baseUrl: (env.RAST_E2E_BASE_URL || "http://127.0.0.1:8731").replace(/\/$/, ""),
  admin: {
    username: env.RAST_E2E_ADMIN_USER || "admin",
    password: env.RAST_E2E_ADMIN_PASSWORD || "",
  },
  users: [
    {
      username: env.RAST_E2E_USER1_USER || "alice",
      password: env.RAST_E2E_USER1_PASSWORD || "",
    },
    {
      username: env.RAST_E2E_USER2_USER || "bob",
      password: env.RAST_E2E_USER2_PASSWORD || "",
    },
  ],
  chromeDeb: env.RAST_E2E_CHROME_DEB || "/tmp/chrome.deb",
  fixturesDir: FIXTURES_DIR,
  resultsDir: RESULTS_DIR,
  screenshotsDir: SCREENSHOTS_DIR,
  tmpDir: TMP_DIR,
  // The dev instance root, used for logs and pid files.
  instanceRoot: INSTANCE_ROOT,
  fixtures: {
    app: join(FIXTURES_DIR, "rast-test-app"),
    archive: join(FIXTURES_DIR, "rast-test-app-1.0.tar.gz"),
    corruptDeb: join(FIXTURES_DIR, "invalid-corrupt.deb"),
    wrongArchDeb: join(FIXTURES_DIR, "wrong-arch.deb"),
    invalidArchive: join(FIXTURES_DIR, "invalid-archive.tar.gz"),
  },
};

export function modeFromInstance() {
  try {
    return readFileSync(join(config.instanceRoot, "mode"), "utf8").trim() || "docker";
  } catch {
    return "docker";
  }
}

export function requireCredentials() {
  if (!config.admin.password) {
    throw new Error(
      "No test credentials: run scripts/e2e/dev-instance.sh up first (it writes tests/e2e/.env.local).",
    );
  }
  return config;
}
